function Initialize-WsmDeltaPlainMerge {
    if('WsmDeltaPlainMerge' -as [type]){return}
    Add-Type -TypeDefinition @'
using System;
using System.IO;
using System.Text;
public static class WsmDeltaPlainMerge {
    public static void Merge(string[] paths,string output){
        if(paths.Length<1 || paths.Length>64)throw new InvalidDataException("Delta hash merge fan-in must be 1..64.");
        var readers=new StreamReader[paths.Length];var heads=new string[paths.Length];
        try{for(int n=0;n<paths.Length;n++){readers[n]=new StreamReader(paths[n],Encoding.ASCII);heads[n]=readers[n].ReadLine();}
            using(var writer=new StreamWriter(output,false,Encoding.ASCII)){while(true){int best=-1;for(int n=0;n<heads.Length;n++){if(heads[n]!=null&&(best<0||StringComparer.Ordinal.Compare(heads[n],heads[best])<0))best=n;}if(best<0)break;writer.WriteLine(heads[best]);heads[best]=readers[best].ReadLine();}}
        }finally{foreach(var reader in readers){if(reader!=null)reader.Dispose();}}
    }
}
'@
}
function Save-WsmDeltaTextRun($State) {
    if(-not $State.Buffer.Count){return};$State.Buffer.Sort([StringComparer]::Ordinal);$path=Join-Path $State.Root ('hashes-'+$State.Serial+'.txt');$State.Serial++
    [IO.File]::WriteAllLines($path,[string[]]$State.Buffer.ToArray(),[Text.Encoding]::ASCII);$State.Runs.Add($path);$State.Known.Add($path);$State.Buffer.Clear()
}
function Add-WsmDeltaTextRun($State,[string]$Line) { $State.Buffer.Add($Line);if($State.Buffer.Count -ge 5000){Save-WsmDeltaTextRun $State} }
function Merge-WsmDeltaTextRuns($State) {
    Save-WsmDeltaTextRun $State
    while($State.Runs.Count -gt 1){$next=New-Object 'System.Collections.Generic.List[string]';for($n=0;$n -lt $State.Runs.Count;$n+=64){$last=[Math]::Min($n+63,$State.Runs.Count-1);$group=@(for($i=$n;$i -le $last;$i++){$State.Runs[$i]});$merged=Join-Path $State.Root ('merged-'+$State.Serial+'.txt');$State.Serial++;Initialize-WsmDeltaPlainMerge;[WsmDeltaPlainMerge]::Merge([string[]]$group,$merged);$State.Known.Add($merged);$next.Add($merged);foreach($part in $group){[IO.File]::Delete($part)}};$State.Runs=$next}
    if($State.Runs.Count){$State.Runs[0]}else{$null}
}
function Add-WsmDeltaZipFile($Archive,[string]$Name,[string]$Path,$CancellationToken=$null) {
    Assert-WsmNoReparse $Path;$entry=$Archive.CreateEntry($Name,[IO.Compression.CompressionLevel]::NoCompression);$input=[IO.File]::Open($Path,'Open','Read','Read');$output=$entry.Open()
    try{$buffer=New-Object byte[] 65536;while(($read=$input.Read($buffer,0,$buffer.Length)) -gt 0){Assert-WsmCancellationBoundary $CancellationToken 'DeltaExportZipMember';$output.Write($buffer,0,$read)}}finally{$output.Dispose();$input.Dispose()}
}
function Copy-WsmDeltaZipEntry($Entry,[string]$Destination,[string]$ExpectedHash,[long]$ExpectedBytes,$CancellationToken=$null) {
    if($Entry.Length -ne $ExpectedBytes -or $ExpectedBytes -gt 128GB){throw 'Delta transport member size mismatch/limit.'}
    Assert-WsmNoReparse $Destination;$parent=[IO.Path]::GetDirectoryName($Destination);if(-not [IO.Directory]::Exists($parent)){[void][IO.Directory]::CreateDirectory($parent)}
    $temp=$Destination+'.'+[Guid]::NewGuid().ToString('N')+'.partial';$source=$Entry.Open();$output=[IO.File]::Open($temp,'CreateNew','Write','None');$sha=[Security.Cryptography.SHA256]::Create();$length=[long]0
    try{$buffer=New-Object byte[] 65536;while(($n=$source.Read($buffer,0,$buffer.Length)) -gt 0){Assert-WsmCancellationBoundary $CancellationToken 'DeltaImportZipMember';$length+=$n;if($length -gt $ExpectedBytes){throw 'Delta ZIP expansion exceeds member size.'};[void]$sha.TransformBlock($buffer,0,$n,$buffer,0);$output.Write($buffer,0,$n)};[void]$sha.TransformFinalBlock((New-Object byte[] 0),0,0);$output.Flush($true);$hash=[BitConverter]::ToString($sha.Hash).Replace('-','').ToLowerInvariant();if($length -ne $ExpectedBytes -or $hash -ine $ExpectedHash){throw 'Delta ZIP member hash/length mismatch.'}}finally{$source.Dispose();$output.Dispose();$sha.Dispose()}
    [IO.File]::Move($temp,$Destination)
}
function Copy-WsmDeltaFileCancellable([string]$Source,[string]$Destination,$CancellationToken=$null,[string]$Phase='DeltaPackageCopy') {
    Assert-WsmNoReparse $Source;Assert-WsmNoReparse $Destination;$parent=[IO.Path]::GetDirectoryName($Destination);if(-not [IO.Directory]::Exists($parent)){[void][IO.Directory]::CreateDirectory($parent)}
    $input=[IO.File]::Open($Source,'Open','Read','Read');$output=[IO.File]::Open($Destination,'CreateNew','Write','None')
    try{$buffer=New-Object byte[] 65536;while(($read=$input.Read($buffer,0,$buffer.Length)) -gt 0){Assert-WsmCancellationBoundary $CancellationToken $Phase;$output.Write($buffer,0,$read)};$output.Flush($true)}finally{$input.Dispose();$output.Dispose()}
}
function Get-WsmDeltaFileHashCancellable([string]$Path,$CancellationToken=$null,[string]$Phase='DeltaHash') {
    $stream=[IO.File]::Open([IO.Path]::GetFullPath($Path),'Open','Read','Read');$sha=[Security.Cryptography.SHA256]::Create()
    try{$buffer=New-Object byte[] 1048576;while(($read=$stream.Read($buffer,0,$buffer.Length)) -gt 0){Assert-WsmCancellationBoundary $CancellationToken $Phase;[void]$sha.TransformBlock($buffer,0,$read,$buffer,0)};[void]$sha.TransformFinalBlock((New-Object byte[] 0),0,0);[BitConverter]::ToString($sha.Hash).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose();$stream.Dispose()}
}
function New-WsmDeltaBoundedRowSpool([string]$Source,[string]$ExpectedHash,[string]$TempRoot,$CancellationToken=$null,[string]$Phase='DeltaBoundedSpool') {
    $reader=New-Object IO.StreamReader([IO.Path]::GetFullPath($Source),[Text.Encoding]::UTF8,$true);$destination=Join-Path $TempRoot ([Guid]::NewGuid().ToString('N')+'.jsonl');$writer=New-Object IO.StreamWriter($destination,$false,(New-Object Text.UTF8Encoding($false)))
    try{Read-WsmBoundedLines $reader 1048576 | ForEach-Object {Assert-WsmCancellationBoundary $CancellationToken $Phase;$writer.WriteLine($_)}}finally{$reader.Dispose();$writer.Dispose()}
    if((Get-WsmDeltaFileHash $Source) -ine $ExpectedHash){[IO.File]::Delete($destination);throw 'Delta row source changed while its bounded spool was being created.'};$destination
}
function Get-WsmDeltaRecordLookup($Package,$ChangesPath,[string]$WorkRoot) {
    $state=[pscustomobject]@{Root=$WorkRoot;Serial=0;Buffer=(New-Object 'System.Collections.Generic.List[string]');Runs=(New-Object 'System.Collections.Generic.List[string]');Known=(New-Object 'System.Collections.Generic.List[string]')}
    $sorted=Read-WsmDeltaSortedIndex (Join-Path $Package.Root 'artifacts.jsonl') $Package.Manifest.ArtifactsHash $Package.Plan $state
    $recordsPath=Join-Path $WorkRoot 'records.jsonl';$recordWriter=New-Object IO.StreamWriter($recordsPath,$false,(New-Object Text.UTF8Encoding($false)))
    $hashRoot=Join-Path $WorkRoot 'hash-runs';[void][IO.Directory]::CreateDirectory($hashRoot);$hashState=[pscustomobject]@{Root=$hashRoot;Serial=0;Buffer=(New-Object 'System.Collections.Generic.List[string]');Runs=(New-Object 'System.Collections.Generic.List[string]');Known=(New-Object 'System.Collections.Generic.List[string]')}
    $changeReader=New-Object IO.StreamReader($ChangesPath,[Text.Encoding]::UTF8,$true);$rowReader=$null;$recordCount=[long]0
    try{
        if($sorted.Path){$rowReader=New-Object IO.StreamReader($sorted.Path,[Text.Encoding]::ASCII)}
        $rowLine=$null;if($rowReader){$rowLine=$rowReader.ReadLine()}
        Read-WsmBoundedLines $changeReader 1048576 | ForEach-Object {
            $change=ConvertFrom-WsmJson $_;$changeKey=ConvertTo-WsmDeltaKeyHex $change.ItemId $change.RelativePath
            if($null -eq $rowLine){if($change.Change -in @('Added','Modified','MetadataOnly')){throw 'Delta references missing current record.'}}
            else{
                $spool=Read-WsmDeltaSpoolRow $rowLine;$compare=[StringComparer]::Ordinal.Compare($changeKey,$spool.Key)
                if($compare -lt 0){if($change.Change -ne 'Deleted'){throw 'Delta changes contain a non-delete without a current record.'}}
                elseif($compare -gt 0){throw 'Current artifact index record is absent from delta changes.'}
                else{
                    $item=@($Package.Plan.Items | Where-Object ItemId -CEQ $spool.Row.ItemId);$sendCertificate=($change.Change -eq 'Unchanged' -and $item.Count -eq 1 -and $item[0].MigrationSpec.Adapter -eq 'Certificate')
                    if($change.Change -in @('Added','Modified','MetadataOnly') -or $sendCertificate){
                        $parts=Get-WsmDeltaRecordParts $spool.Row;if($parts.RecordHash -cne $change.CurrentRecordHash){throw 'Delta current record hash differs from current index.'}
                        $recordWriter.WriteLine((ConvertTo-Json -InputObject ([pscustomobject][ordered]@{Change=$change.Change;Record=$spool.Row}) -Depth 25 -Compress))
                        $recordCount++
                        if(($change.Change -in @('Added','Modified') -or $sendCertificate) -and -not $spool.Row.Directory){foreach($chunk in $spool.Row.Data.Chunks){Add-WsmDeltaTextRun $hashState ([string]$chunk.Hash+'|'+([long]$chunk.Bytes).ToString([Globalization.CultureInfo]::InvariantCulture))}}
                    }
                    $rowLine=$rowReader.ReadLine()
                }
            }
        }
        if($null -ne $rowLine){throw 'Current artifact index record is absent from delta changes.'}
        $recordWriter.Flush()
    }finally{$recordWriter.Dispose();$changeReader.Dispose();if($rowReader){$rowReader.Dispose()}}
    foreach($path in $state.Known){if([IO.File]::Exists($path)){[IO.File]::Delete($path)}}
    [pscustomobject]@{RecordsPath=$recordsPath;RecordCount=$recordCount;HashRuns=$hashState}
}
function Export-WsmArtifactDeltaZip {
    [CmdletBinding()]param([Parameter(Mandatory)][string]$BaseManifestPath,[Parameter(Mandatory)][string]$BaseManifestHash,[Parameter(Mandatory)][string]$BasePlanPath,[Parameter(Mandatory)][string]$BasePlanHash,[Parameter(Mandatory)][string]$CurrentManifestPath,[Parameter(Mandatory)][string]$CurrentManifestHash,[Parameter(Mandatory)][string]$CurrentPlanPath,[Parameter(Mandatory)][string]$CurrentPlanHash,[Parameter(Mandatory)][string]$SummaryPath,[Parameter(Mandatory)][string]$SummaryHash,[Parameter(Mandatory)][string]$ChangesPath,[Parameter(Mandatory)][string]$OutputPath,$CancellationToken=$null)
    $checked=Test-WsmArtifactDeltaManifest -SummaryPath $SummaryPath -SummaryHash $SummaryHash -ChangesPath $ChangesPath -BaseManifestPath $BaseManifestPath -BaseManifestHash $BaseManifestHash -BasePlanPath $BasePlanPath -BasePlanHash $BasePlanHash -CurrentManifestPath $CurrentManifestPath -CurrentManifestHash $CurrentManifestHash -CurrentPlanPath $CurrentPlanPath -CurrentPlanHash $CurrentPlanHash
