    $hashFile=Merge-WsmDeltaTextRuns $stage.HashRuns;$blobPath=Join-Path $root 'blobs.bin';$blobIndexPath=Join-Path $root 'blobs.jsonl';$blobWriter=New-Object IO.StreamWriter($blobIndexPath,$false,(New-Object Text.UTF8Encoding($false)));$blobOutput=[IO.File]::Open($blobPath,'CreateNew','Write','None');$offset=[long]0
