    $baseRoot=[IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($BaseManifestPath));$currentRoot=[IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($CurrentManifestPath));$members=@(
        [pscustomobject]@{Name='base/manifest.json';Path=$BaseManifestPath},[pscustomobject]@{Name='base/plan.json';Path=$BasePlanPath},[pscustomobject]@{Name='base/artifacts.jsonl';Path=(Join-Path $baseRoot 'artifacts.jsonl')},
        [pscustomobject]@{Name='current/manifest.json';Path=$CurrentManifestPath},[pscustomobject]@{Name='current/plan.json';Path=$CurrentPlanPath},[pscustomobject]@{Name='current/artifacts.jsonl';Path=(Join-Path $currentRoot 'artifacts.jsonl')},[pscustomobject]@{Name='current/freeze.json';Path=(Join-Path $currentRoot 'freeze.json')},
        [pscustomobject]@{Name='delta/summary.json';Path=$SummaryPath},[pscustomobject]@{Name='delta/changes.jsonl';Path=$ChangesPath},[pscustomobject]@{Name='delta/records.jsonl';Path=$stage.RecordsPath},[pscustomobject]@{Name='delta/blobs.jsonl';Path=$blobIndexPath},[pscustomobject]@{Name='delta/blobs.bin';Path=$blobPath})
    $transport=[pscustomobject][ordered]@{SchemaVersion=1;ToolVersion=$script:ToolVersion;Kind='ArtifactDeltaTransport';PairId=$checked.Summary.PairId;PlanHash=$checked.Summary.PlanHash;BaseManifestHash=$BaseManifestHash.ToLowerInvariant();CurrentManifestHash=$CurrentManifestHash.ToLowerInvariant();SummaryHash=$SummaryHash.ToLowerInvariant();ChangesHash=(Get-WsmDeltaFileHash $ChangesPath);Members=@(foreach($member in $members){if(-not [IO.File]::Exists($member.Path)){throw ('Required delta member missing: '+$member.Path)};[pscustomobject]@{Name=$member.Name;Bytes=(New-Object IO.FileInfo($member.Path)).Length;SHA256=(Get-WsmDeltaFileHash $member.Path)}});BlobBytes=$offset;CreatedUtc=(Get-WsmUtc);Mode='IsolatedPilot'}
