    $temp=$out+'.'+[Guid]::NewGuid().ToString('N')+'.partial';$file=[IO.File]::Open($temp,'CreateNew','ReadWrite','None');$archive=$null
    try{Add-Type -AssemblyName System.IO.Compression;$archive=New-Object IO.Compression.ZipArchive($file,[IO.Compression.ZipArchiveMode]::Create,$true);Add-WsmDeltaZipFile $archive 'transport.json' $transportPath $CancellationToken;foreach($member in $members){Assert-WsmCancellationBoundary $CancellationToken 'DeltaExportMember';Add-WsmDeltaZipFile $archive $member.Name $member.Path $CancellationToken};$archive.Dispose();$archive=$null;$file.Flush($true)}finally{if($archive){$archive.Dispose()};$file.Dispose()}
    try{[IO.File]::Move($temp,$out)}finally{if([IO.File]::Exists($temp)){[IO.File]::Delete($temp)}}
    foreach($path in @($stage.RecordsPath,$blobPath,$blobIndexPath,$transportPath)+@($stage.HashRuns.Known)){if($path -and [IO.File]::Exists($path)){[IO.File]::Delete($path)}}
