    [pscustomobject]@{Path=$out;SHA256=(Get-WsmDeltaFileHash $out);Bytes=(New-Object IO.FileInfo($out)).Length;PairId=$transport.PairId;BaseManifestHash=$transport.BaseManifestHash;CurrentManifestHash=$transport.CurrentManifestHash;ChangedRecords=$stage.RecordCount;Mode='IsolatedPilot'}
}
function Test-WsmDeltaTransportContents([string]$Root,$Transport,$CancellationToken=$null) {
    Assert-WsmEnvelope $Transport 'ArtifactDeltaTransport';Assert-WsmId $Transport.PairId
    if($Transport.PlanHash -notmatch '^[a-f0-9]{64}$' -or $Transport.BaseManifestHash -notmatch '^[a-f0-9]{64}$' -or $Transport.CurrentManifestHash -notmatch '^[a-f0-9]{64}$' -or $Transport.SummaryHash -notmatch '^[a-f0-9]{64}$' -or $Transport.ChangesHash -notmatch '^[a-f0-9]{64}$'){throw 'Invalid delta transport binding hashes.'}
    $expectedNames=@('base/manifest.json','base/plan.json','base/artifacts.jsonl','current/manifest.json','current/plan.json','current/artifacts.jsonl','current/freeze.json','delta/summary.json','delta/changes.jsonl','delta/records.jsonl','delta/blobs.jsonl','delta/blobs.bin')
    if($Transport.Members.Count -ne $expectedNames.Count){throw 'Delta transport member list is incomplete.'};$memberMap=@{}
    foreach($member in $Transport.Members){Assert-WsmCancellationBoundary $CancellationToken 'DeltaTransportMember';Assert-WsmFields $member @('Name','Bytes','SHA256') @('Name','Bytes','SHA256');if($expectedNames -cnotcontains $member.Name -or $memberMap.ContainsKey([string]$member.Name) -or $member.SHA256 -notmatch '^[a-f0-9]{64}$' -or $member.Bytes -lt 0){throw 'Delta transport contains an unsafe/duplicate member descriptor.'};$memberMap[[string]$member.Name]=$member}
    foreach($name in $expectedNames){Assert-WsmCancellationBoundary $CancellationToken 'DeltaTransportMemberHash';if(-not $memberMap.ContainsKey($name)){throw ('Delta transport missing member descriptor: '+$name)};$relative=$name.Replace('/','\');$path=Join-Path $Root $relative;Assert-WsmNoReparse $path;if(-not [IO.File]::Exists($path) -or (New-Object IO.FileInfo($path)).Length -ne $memberMap[$name].Bytes -or (Get-WsmDeltaFileHashCancellable $path $CancellationToken 'DeltaTransportMemberHash') -ine $memberMap[$name].SHA256){throw ('Delta transport member hash/size mismatch: '+$name)}}
    if((Get-WsmDeltaFileHashCancellable (Join-Path $Root 'delta\changes.jsonl') $CancellationToken 'DeltaTransportChangesHash') -ine $Transport.ChangesHash){throw 'Delta changes do not match transport binding.'}
    $baseManifest=Join-Path $Root 'base\manifest.json';$basePlan=Join-Path $Root 'base\plan.json';$currentManifest=Join-Path $Root 'current\manifest.json';$currentPlan=Join-Path $Root 'current\plan.json';$summary=Join-Path $Root 'delta\summary.json';$changes=Join-Path $Root 'delta\changes.jsonl'
