    $validated=Test-WsmArtifactDeltaManifest -SummaryPath $summary -SummaryHash $Transport.SummaryHash -ChangesPath $changes -BaseManifestPath $baseManifest -BaseManifestHash $Transport.BaseManifestHash -BasePlanPath $basePlan -BasePlanHash $Transport.PlanHash -CurrentManifestPath $currentManifest -CurrentManifestHash $Transport.CurrentManifestHash -CurrentPlanPath $currentPlan -CurrentPlanHash $Transport.PlanHash
    $recordsPath=Join-Path $Root 'delta\records.jsonl';$spoolRoot=Join-Path ([IO.Path]::GetTempPath()) ('wsm-delta-bounded-'+[Guid]::NewGuid().ToString('N'));[void][IO.Directory]::CreateDirectory($spoolRoot);$changesSpool=$null;$recordsSpool=$null;$changesReader=$null;$recordsReader=$null
    $payloadRoot=Join-Path $Root 'current\payload'
    try{$changesSpool=New-WsmDeltaBoundedRowSpool $changes $Transport.ChangesHash $spoolRoot $CancellationToken 'DeltaTransportChangeSpool';$recordsSpool=New-WsmDeltaBoundedRowSpool $recordsPath $memberMap['delta/records.jsonl'].SHA256 $spoolRoot $CancellationToken 'DeltaTransportRecordSpool';$changesReader=New-Object IO.StreamReader($changesSpool,[Text.Encoding]::UTF8,$true);$recordsReader=New-Object IO.StreamReader($recordsSpool,[Text.Encoding]::UTF8,$true);$recordLine=$recordsReader.ReadLine();while($null -ne ($changeLine=$changesReader.ReadLine())){Assert-WsmCancellationBoundary $CancellationToken 'DeltaTransportChangeRow';$change=ConvertFrom-WsmJson $changeLine;$planItem=@($currentApprovedPlan.Items | Where-Object ItemId -CEQ $change.ItemId);$sendCertificate=($change.Change -eq 'Unchanged' -and $planItem.Count -eq 1 -and $planItem[0].MigrationSpec.Adapter -eq 'Certificate');if($change.Change -in @('Added','Modified','MetadataOnly') -or $sendCertificate){if($null -eq $recordLine){throw 'Transport omits a changed current artifact record.'};$recordEnvelope=ConvertFrom-WsmJson $recordLine;Assert-WsmFields $recordEnvelope @('Change','Record') @('Change','Record');if($recordEnvelope.Change -cne $change.Change){throw 'Transport record operation differs from delta.'};$row=$recordEnvelope.Record;$key=ConvertTo-WsmDeltaKeyHex $row.ItemId $row.RelativePath;if($key -cne (ConvertTo-WsmDeltaKeyHex $change.ItemId $change.RelativePath) -or (Get-WsmDeltaRecordParts $row).RecordHash -cne $change.CurrentRecordHash){throw 'Transport changed record does not match the delta/index binding.'};if(($change.Change -in @('Added','Modified') -or $sendCertificate) -and -not $row.Directory -and [IO.Directory]::Exists($payloadRoot)){foreach($chunk in $row.Data.Chunks){Assert-WsmCancellationBoundary $CancellationToken 'DeltaTransportChunk';$blob=Join-Path $payloadRoot ($chunk.Hash+'.blob');if(-not [IO.File]::Exists($blob) -or (New-Object IO.FileInfo($blob)).Length -ne $chunk.Bytes -or (Get-Wsm