    [pscustomobject]@{Valid=$true;Transport=$Transport;BaseManifest=$base;CurrentManifest=$current;Summary=$validated.Summary;ChangedRecords=$validated.Summary.Counts.Added+$validated.Summary.Counts.Modified+$validated.Summary.Counts.MetadataOnly;Root=[IO.Path]::GetFullPath($Root)}
}
function Import-WsmArtifactDeltaZip {
    [CmdletBinding()]param([Parameter(Mandatory)][string]$TransportPath,[Parameter(Mandatory)][string]$ExpectedHash,[Parameter(Mandatory)][string]$OutputDirectory,$CancellationToken=$null)
