function Assert-WsmDeltaStagedAdapters($CurrentPackage,$State,[string]$Phase,[bool]$RequireManualEvidence=$true) {
    $manualItems=@($CurrentPackage.Plan.Items | Where-Object {$_.Decision -eq 'Include' -and $_.MigrationSpec.Adapter -eq 'ManualWorkflow'})
    if(($manualItems.Count -gt 0) -ne ($State.Stage -eq 'ManualEvidenceRequired')){throw 'Delta base stage does not match the included ManualWorkflow contract.'}
    foreach($item in $CurrentPackage.Plan.Items){if($item.Decision -ne 'Include' -or $item.MigrationSpec.Adapter -eq 'FileScope'){continue};$spec=$item.MigrationSpec;$owners=@($State.Items | Where-Object ItemId -CEQ $item.ItemId)
        if($owners.Count -ne 1){throw ('Delta staged adapter has no unique durable ownership/status row: '+$item.ItemId)};$owner=$owners[0]
        if($spec.Adapter -eq 'ManualWorkflow'){
            if($owner.Status -cne 'ManualEvidenceRequired' -or $owner.CreatedByTool -ne $false -or ($RequireManualEvidence -and -not (Test-WsmEvidence $State $item.ItemId ManualRestore $State.ManifestHash))){throw ('Delta ManualWorkflow lacks current staged procedure evidence; it remains manual: '+$item.ItemId)}
            continue
