        if($owner.Status -notin @('Succeeded','RebootRequired')){throw ('Delta staged adapter ownership/status is not complete: '+$item.ItemId)}
        if($owner.Status -eq 'RebootRequired'){Assert-WsmRebootCompleted $owner}
