        if(-not $check.Passed){throw ('Delta staged adapter readback failed for '+$item.ItemId+': '+(@($check.Problems) -join '; '))}
        if($spec.Adapter -eq 'WindowsFeature' -and $owner.CreatedByTool){[void](Test-WsmInstallerConsumers $spec.Desired $owner.InstallerSafety Staged)}
    }
}
