        $promotionState=Get-WsmOperationState $paths $currentPackage -AllowRecovery;Assert-WsmDeltaStagedAdapters $currentPackage $promotionState 'BeforeGenerationPromotion'
        $state=Write-WsmDeltaOperationState $paths $currentPackage $transaction;$transaction.Phase='Completed';$transaction.UpdatedUtc=Get-WsmUtc;Write-WsmJson $transactionPath $transaction
        [pscustomobject]@{PairId=$state.PairId;ManifestHash=$state.ManifestHash;Generation=$state.Generation;Stage=$state.Stage;ChangedItems=@($transaction.Operations | ForEach-Object ItemId);TransactionPath=$transactionPath;DeltaPackageManifestPath=$state.DeltaPackageManifestPath;DeltaPackageManifestHash=$state.DeltaPackageManifestHash;Mode='IsolatedPilot';ProductionVerified=$false}
    }
}
function Repair-WsmArtifactDeltaRestore {
    [CmdletBinding()]param([Parameter(Mandatory)][string]$TransportPath,[Parameter(Mandatory)][string]$ExpectedTransportHash,[Parameter(Mandatory)][string]$ImportedDirectory,[Parameter(Mandatory)][string]$TargetStateDirectory,[object[]]$GeneralHostEvidence=@(),$CancellationToken=$null)
    Invoke-WsmArtifactDeltaRestore -TransportPath $TransportPath -ExpectedTransportHash $ExpectedTransportHash -ImportedDirectory $ImportedDirectory -TargetStateDirectory $TargetStateDirectory -GeneralHostEvidence $GeneralHostEvidence -CancellationToken $CancellationToken -Confirm:$false
}
